import { parseResponse } from "http/parseResponse"
import { ServerError }   from "http/ServerError"
import {
  BeforeRequestInterceptor,
  Configuration,
  ErrorInterceptor,
  RequestConfig,
  RequestParams,
  ResponseBody,
  ServerErrorDetails
} from "http/types"
import { toQueryString } from "http/urlHelpers"
import { Logger }        from "utils/Logger"
import { isString }      from "utils/typeCheckers"

const logger = new Logger("request")

export const request = async <T>(rp: RequestParams & Configuration, originalRequestInitiatedAt?: number): Promise<T> => {
  const {
          afterRequestInterceptor,
          beforeRequest,
          beforeRequestInterceptor,
          domain,
          errorInterceptor,
          extraLogFields,
          method,
          uri,
          body,
          otherOptions,
          query,
          unauthInterceptor,
        } = rp
  const extra = extraLogFields?.() ?? {}
  return await watchForErrors(errorInterceptor, async () => {
    const requestInitiatedAt = originalRequestInitiatedAt ?? Date.now()
    logger.writeInfo("[request:start]", { method, uri, query, ...extra })
    logger.writeInfo("[request:beforeHook:start]", { method, uri, ...extra })
    await beforeRequest(uri)
    logger.writeInfo("[request:beforeHook:done]", { method, uri, ...extra })

    const { query: finalizedQuery, ...config } = fetchConfig(
      method, beforeRequestInterceptor, body, query
    )

    const queryString    = finalizedQuery ? `?${toQueryString(finalizedQuery)}` : ""
    const url            = `${domain}${uri}${queryString}`
    const resp: Response = await fetch(url, config as RequestInit)
    const { status }     = resp
    logger.writeInfo("[request:response]", { method, uri, status, ...extra })

    if (isUnauthorized(status)) {
      await unauthInterceptor(uri, requestInitiatedAt)
      return await retry(rp, requestInitiatedAt)
    }

    const respBody = await parseResponse(resp)
    logger.writeInfo("[request:done]", { method, uri, status, ...extra })
    if (isSuccessResponse(status)) {
      return respBody
             ? afterRequestInterceptor(respBody as ResponseBody, otherOptions)
             : undefined
    }
    bubbleServerError(uri, respBody, status)
  })

}

const bubbleServerError = (uri: string, respBody: any, status: number) => {
  const errorResp: string | Omit<ServerErrorDetails, "status"> = respBody
  const errorDetails: ServerErrorDetails                       =
          isString(respBody)
          ? { status, error: respBody, type: ServerError.ERROR_TYPES.SYSTEM, uri }
          : {
              ...errorResp as Omit<ServerErrorDetails, "status">,
              status,
              type: respBody.type ?? ServerError.ERROR_TYPES.SYSTEM,
              uri,
            }

  throw new ServerError(errorDetails)
}

const fetchConfig = (
  method: string,
  intercept: BeforeRequestInterceptor,
  body?: Object,
  query?: Object
): RequestConfig => {
  const config = intercept({
    body,
    method,
    query,
    cache:    "no-cache",
    headers:  { "content-type": "application/json" },
    redirect: "follow",
  })
  // @ts-ignore
  return { ...config, body: finalizeBody(config), }
}

const finalizeBody = ({ headers = {}, body }: RequestInit) => {
  if (!body) return

  // @ts-ignore
  return headers["content-type"] === "application/json"
         ? JSON.stringify(body)
         : body
}

const isSuccessResponse = (status: number): boolean => status < 400
const isUnauthorized    = (status: number): boolean => status === 401
const retry             = <T>(rp: RequestParams & Configuration, originalRequestInitiatedAt: number) =>
  request<T>(rp, originalRequestInitiatedAt)
const watchForErrors    = async (
  errorInterceptor: ErrorInterceptor,
  f: Function,
): Promise<any> => {
  try {
    return await f()
  } catch (e) {
    if (!(e instanceof Error)) throw e

    const shouldNotBubble = await errorInterceptor(e)
    if (shouldNotBubble) return

    throw e
  }
}
